def solve(prices, quantities):
    if not prices:
        return []

    # Use a dictionary to accumulate sums for each price
    # Key: price, Value: [sum_of_products, sum_of_quantities]
    agg = {}
    for p, q in zip(prices, quantities):
        if p not in agg:
            agg[p] = [0, 0]
        agg[p][0] += p * q
        agg[p][1] += q

    result = []
    for p in sorted(agg.keys()):
        total_product, total_qty = agg[p]
        avg = total_product / total_qty
        # Convert to float if not integer to maintain precision, 
        # but q/kdb+ usually handles decimals natively. 
        # We return standard Python floats.
        result.append((p, avg))

    return result

