def solve(matrix):
    if not matrix or len(matrix) < 2:
        return []
    R = len(matrix)
    C = len(matrix[0])
    if C < 2:
        return []

    result = []
    # Iterate over valid top-left corners: rows 0 to R-2, cols 0 to C-2
    for r in range(R - 1):
        for c in range(C - 1):
            # Sum the 2x2 block: (r,c), (r,c+1), (r+1,c), (r+1,c+1)
            s = (matrix[r][c] + matrix[r][c+1] + 
                 matrix[r+1][c] + matrix[r+1][c+1])
            result.append(s)
    return result

