def solve(arr, w):
    n = len(arr)
    if n == 0 or w > n or w <= 0:
        return []
    if w == 1:
        return list(arr)

    # Monotonic deque approach for O(n) sliding window maximum
    # We store indices in the deque such that their corresponding values are in descending order
    from collections import deque
    dq = deque()
    result = []

    for i in range(n):
        # Remove indices that are out of the current window
        if dq and dq[0] == i - w:
            dq.popleft()

        # Maintain the monotonic property: remove indices whose values are smaller than current
        while dq and arr[dq[-1]] <= arr[i]:
            dq.pop()

        dq.append(i)

        # Once we have processed at least w elements, record the max
        if i >= w - 1:
            result.append(arr[dq[0]])

    return result

