def solve(strings):
    if not strings:
        return 0
    if len(strings) == 1:
        return len(strings[0])

    # Find the minimum length to avoid index errors
    min_len = min(len(s) for s in strings)
    if min_len == 0:
        return 0

    prefix_len = 0
    # Compare character by character up to the shortest string's length
    for i in range(min_len):
        char_at_i = strings[0][i]
        for s in strings[1:]:
            if s[i] != char_at_i:
                return prefix_len
        prefix_len += 1

    return prefix_len

