def solve(values, queries, k):
    if not values:
        return [0] * len(queries)

    # Sort values to allow efficient range queries if needed, though simple scan is O(N*M)
    # For a "medium" q/kdb+ test, the user might expect a sort + binary search or a keyed approach.
    # However, the reference solution just needs to be correct and fast enough for small N.
    # To make it robust for the "medium" difficulty implying vectorization, we implement a clean loop.
    # In q, this would be a join or a range scan.

    results = []
    sorted_vals = sorted(values) # Sorting helps in a real kdb+ solution using binary search or range

    for q in queries:
        lower = q - k
        upper = q + k
        current_sum = 0
        for v in sorted_vals:
            if v > upper:
                break
            if v >= lower:
                current_sum += v
        results.append(current_sum)

    return results

