def solve(prices, k):
    if not prices or k <= 0:
        return []
    n = len(prices)
    if k > n:
        return []
    result = []
    from collections import deque
    dq = deque() # stores indices

    for i in range(n):
        # Remove elements out of the current window from the front
        while dq and dq[0] <= i - k:
            dq.popleft()

        # Remove elements smaller than current from the back (they are useless)
        while dq and prices[dq[-1]] <= prices[i]:
            dq.pop()

        dq.append(i)

        # The front of the deque is the max for the current window
        if i >= k - 1:
            result.append(prices[dq[0]])

    return result

