def solve(prices):
    if len(prices) < 2:
        return 0

    max_gain = 0
    current_start = 0

    for i in range(1, len(prices)):
        # If current price is not strictly greater than previous, reset the sequence start
        if prices[i] <= prices[i - 1]:
            current_start = i
            continue

        # Calculate gain from the start of the current increasing sequence
        gain = prices[i] - prices[current_start]
        if gain > max_gain:
            max_gain = gain

    return max_gain

