def solve(changes, w):
    if len(changes) < w:
        return None
    # Compute the sum of the first window
    current_sum = sum(changes[:w])
    max_sum = current_sum

    # Slide the window
    for i in range(w, len(changes)):
        current_sum += changes[i] - changes[i - w]
        if current_sum > max_sum:
            max_sum = current_sum

    return max_sum

